// ---------------------------------------------------------------------------
// Aplana lo que llega, venga de donde venga. Dos proveedores con dos formatos
// distintos entran por aquí y salen con la misma forma:
//   - Meta manda JSON anidado, y un solo POST puede traer varios eventos.
//   - Twilio manda un formulario plano, un evento por POST.
// Cada uno puede traer mensajes entrantes o acuses de entrega.
// ---------------------------------------------------------------------------
const eventos = [];

for (const item of $input.all()) {
  const b = item.json.body ?? item.json;

  // --- Twilio: se reconoce por el SID del mensaje ---------------------------
  if (b.MessageSid || b.SmsSid || b.SmsMessageSid) {
    const sid = String(b.MessageSid ?? b.SmsSid ?? b.SmsMessageSid);

    if (b.MessageStatus || b.SmsStatus) {
      eventos.push({ json: {
        clase: 'estado', canal: 'sms',
        wamid: sid,
        estado_entrega: String(b.MessageStatus ?? b.SmsStatus),
        destinatario: String(b.To ?? ''),
        // Twilio no manda el precio en el callback; se cobra al aceptarlo,
        // así que lo damos por facturable salvo que fallara antes de salir.
        facturable: ['sent', 'delivered', 'undelivered'].includes(String(b.MessageStatus ?? b.SmsStatus)) ? 'si' : '',
        categoria_real: '',
        motivo_error: b.ErrorCode ? String(b.ErrorCode) + ': ' + String(b.ErrorMessage ?? '') : '',
      }});
    } else {
      eventos.push({ json: {
        clase: 'mensaje', canal: 'sms',
        remitente_negocio: String(b.To ?? ''),   // el número del negocio
        // Si el negocio envía por Messaging Service, el número de destino no
        // basta para saber de quién es: el SID del servicio sí.
        remitente_servicio: String(b.MessagingServiceSid ?? ''),
        from: String(b.From ?? ''),
        wamid: sid,
        tipo_mensaje: 'text',
        payload_boton: '',                        // el SMS no tiene botones
        texto: String(b.Body ?? ''),
        nombre_perfil: '',
        timestamp: '',
      }});
    }
    continue;
  }

  // --- Meta: sobre anidado --------------------------------------------------
  for (const entrada of (b.entry ?? [])) {
    for (const cambio of (entrada.changes ?? [])) {
      const v = cambio.value ?? {};
      const pnid = v.metadata?.phone_number_id ?? '';

      for (const m of (v.messages ?? [])) {
        const perfil = (v.contacts ?? []).find(c => c.wa_id === m.from);
        eventos.push({ json: {
          clase: 'mensaje', canal: 'whatsapp',
          remitente_negocio: pnid,
          from: String(m.from ?? ''),
          wamid: String(m.id ?? ''),
          tipo_mensaje: String(m.type ?? ''),
          payload_boton: m.button?.payload ?? m.interactive?.button_reply?.id ?? '',
          texto: m.text?.body ?? m.button?.text ?? m.interactive?.button_reply?.title ?? '',
          nombre_perfil: perfil?.profile?.name ?? '',
          timestamp: m.timestamp ?? '',
        }});
      }

      for (const s of (v.statuses ?? [])) {
        eventos.push({ json: {
          clase: 'estado', canal: 'whatsapp',
          wamid: String(s.id ?? ''),
          estado_entrega: String(s.status ?? ''),
          destinatario: String(s.recipient_id ?? ''),
          // Meta sí dice si lo facturó y en qué categoría lo clasificó ELLA.
          facturable: s.pricing?.billable === true ? 'si'
                    : s.pricing?.billable === false ? 'no' : '',
          categoria_real: s.pricing?.category ?? '',
          motivo_error: (s.errors ?? []).map(e => e.code + ': ' + (e.title ?? '')).join(' | '),
        }});
      }
    }
  }
}

console.log('eventos=' + JSON.stringify(eventos.map(e => e.json.canal + ':' + e.json.clase)));
return eventos;

// ---------------------------------------------------------------------------
// Identifica al cliente, deduce la intención y arma la respuesta y el aviso.
// Corre una vez por item, y sirve a los dos canales.
// ---------------------------------------------------------------------------
const ev       = $json;
const negocios = $('Leer negocios').all().map(i => i.json);
const clientes = $('Leer clientes').all().map(i => i.json);

const soloDigitos = t => String(t ?? '').replace(/[^0-9]/g, '');
const rellenar = (p, v) => String(p ?? '').replace(/\{(\w+)\}/g, (m, k) => (v[k] ?? m));
const formulario = o => Object.entries(o)
  .map(([k, x]) => encodeURIComponent(k) + '=' + encodeURIComponent(x)).join('&');

// Ni WhatsApp ni los operadores devuelven siempre el número como se envió.
// México quita o pone un "1" tras el 52; Argentina un "9" tras el 54; y en
// EE.UU. el mismo número aparece con y sin el 1 de país.
function variantes(tel) {
  const d = soloDigitos(tel);
  const v = new Set([d]);
  if (d.startsWith('521') && d.length === 13) v.add('52' + d.slice(3));
  if (d.startsWith('52')  && d.length === 12) v.add('521' + d.slice(2));
  if (d.startsWith('549') && d.length === 13) v.add('54' + d.slice(3));
  if (d.startsWith('54')  && d.length === 12) v.add('549' + d.slice(2));
  if (d.startsWith('1')   && d.length === 11) v.add(d.slice(1));
  if (d.length === 10)                        v.add('1' + d);
  return [...v];
}

const indice = {};
for (const c of clientes) {
  for (const k of variantes(c.telefono)) if (k.length >= 10) indice[k] = c;
}
let cliente = null;
for (const k of variantes(ev.from)) if (indice[k]) { cliente = indice[k]; break; }

const negocioId = cliente ? String(cliente.negocio_id).trim() : '';
const porRemitente = n => {
  const r = String(ev.remitente_negocio ?? '').trim();
  const svc = String(ev.remitente_servicio ?? '').trim();
  const rem = String(n.sms_remitente ?? '').trim();
  if (svc && rem && svc === rem) return true;
  if (!r) return false;
  return String(n.phone_number_id ?? '').trim() === r
      || (!!soloDigitos(rem) && soloDigitos(rem) === soloDigitos(r));
};
const negocio = negocios.find(n => String(n.negocio_id).trim() === negocioId)
             || negocios.find(porRemitente)
             || {};

const canal = String(ev.canal || negocio.canal || 'sms').trim().toLowerCase();
const nombre = String(cliente?.nombre ?? ev.nombre_perfil ?? '').trim().split(/\s+/)[0] || 'Hola';
const negocioCorto = String(negocio.nombre_corto || negocio.nombre || 'la barberia').trim();

// --- Intención --------------------------------------------------------------
const normalizar = s => String(s ?? '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Twilio intercepta por su cuenta STOP, END, QUIT, CANCEL y UNSUBSCRIBE: esos
// nunca llegan aquí. Pero desde abril de 2025 hay que honrar la revocación
// hecha por "cualquier método razonable", y esas frases SÍ llegan. Esta lista
// existe para atraparlas.
const PALABRAS_BAJA = [
  'baja','stop','alto','parar','no me escriban','no quiero mensajes','ya no me manden',
  'quitame','quiteme','sacame de la lista','borrame','eliminar','desuscribir',
  'unsubscribe','remove me','take me off','opt out','optout','do not text','dont text',
  'stop texting','no more texts','leave me alone','cancelar','revoke',
];
const PALABRAS_SI = [
  'si','sii','claro','va','dale','agendame','agenda','quiero','sale','ok','okay',
  'de una','me interesa','apartame','apartar','yes','yeah','yep','sure','book me','sounds good',
];
const PALABRAS_NO = [
  'no','ahora no','luego','despues','mas adelante','no gracias','todavia no',
  'not now','later','maybe later','no thanks',
];

const texto = normalizar(ev.texto);
const empieza = lista => lista.some(p => texto === p || texto.startsWith(p + ' '));
const contiene = lista => lista.some(p => texto.includes(p));

let intencion;
if (ev.payload_boton) {
  intencion = ({ AGENDAR: 'agendar', AHORA_NO: 'ahora_no', BAJA: 'baja' })[ev.payload_boton] ?? 'otro';
} else if (contiene(PALABRAS_BAJA)) {
  intencion = 'baja';
} else if (empieza(PALABRAS_SI)) {
  intencion = 'agendar';
} else if (empieza(PALABRAS_NO)) {
  intencion = 'ahora_no';
} else {
  // Texto libre que no encaja: no adivinamos, lo lee un humano.
  intencion = 'otro';
}

// Respuestas sin tildes ni emoji: en SMS un solo carácter fuera de GSM-7
// triplica el costo, y estas respuestas se mandan a todo el que contesta.
const RESPUESTAS = {
  baja:     'Listo, no volveras a recibir mensajes nuestros.',
  agendar:  'Perfecto ' + nombre + '. En un momento te escriben de ' + negocioCorto + ' para darte hora.',
  ahora_no: 'Sin problema ' + nombre + '. Aqui seguimos cuando lo necesites.',
  otro:     'Gracias por escribir ' + nombre + '. Ya avisamos a ' + negocioCorto + ' y te contactan enseguida.',
};

const telefonoCliente = soloDigitos(ev.from);
const telDueno = soloDigitos(negocio.telefono_dueno);
const remitente = String(negocio.sms_remitente || '').trim();
const esSms = canal === 'sms';

// Al dueño solo se le avisa cuando hay algo que hacer.
const avisarDueno = (intencion === 'agendar' || intencion === 'otro') && !!telDueno
  && (esSms ? !!String(negocio.sms_aviso || '').trim() : !!String(negocio.plantilla_aviso || '').trim());

const valsAviso = {
  negocio: negocioCorto,
  nombre_completo: String(cliente?.nombre ?? ev.nombre_perfil ?? 'Un cliente').trim(),
  telefono: telefonoCliente,
};

let respForm = '', avisoForm = '', respPayload = null, avisoPayload = null;

if (esSms) {
  const rem = remitente.startsWith('MG') ? { MessagingServiceSid: remitente } : { From: remitente };
  respForm = formulario({ To: '+' + telefonoCliente, Body: RESPUESTAS[intencion], ...rem });
  if (avisarDueno) {
    avisoForm = formulario({ To: '+' + telDueno, Body: rellenar(negocio.sms_aviso, valsAviso), ...rem });
  }
} else {
  respPayload = {
    messaging_product: 'whatsapp', recipient_type: 'individual', to: telefonoCliente,
    type: 'text', text: { preview_url: false, body: RESPUESTAS[intencion] },
  };
  if (avisarDueno) {
    avisoPayload = {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: telDueno, type: 'template',
      template: {
        name: String(negocio.plantilla_aviso).trim(),
        language: { code: String(negocio.idioma_plantilla || 'es_MX').trim() },
        components: [{ type: 'body', parameters: [
          { type: 'text', text: valsAviso.negocio },
          { type: 'text', text: valsAviso.nombre_completo },
          { type: 'text', text: valsAviso.telefono },
        ]}],
      },
    };
  }
}

return { json: {
  intencion, canal, es_sms: esSms,
  encontrado: !!cliente,
  cliente_id: cliente ? String(cliente.cliente_id).trim() : '',
  negocio_id: negocioId,
  telefono: telefonoCliente,
  phone_number_id: String(negocio.phone_number_id || '').trim(),
  actualizar_cliente: !!cliente,
  nuevo_optout: intencion === 'baja' ? 'si' : String(cliente?.optout ?? 'no'),
  nuevo_estado: intencion === 'baja' ? 'baja'
              : intencion === 'agendar' ? 'interesado'
              : intencion === 'ahora_no' ? 'contactado' : 'respondio',
  respuesta_form: respForm,
  respuesta_payload: respPayload,
  avisar_dueno: avisarDueno,
  aviso_form: avisoForm,
  aviso_payload: avisoPayload,
  fila_log: {
    timestamp: new Date().toISOString(),
    negocio_id: negocioId,
    cliente_id: cliente ? String(cliente.cliente_id).trim() : '',
    telefono: telefonoCliente,
    canal,
    tipo: 'respuesta',
    categoria: esSms ? 'entrante' : 'service',
    plantilla: '',
    encoding: '', segmentos: '',
    wamid: ev.wamid,
    estado: 'recibido',
    error_code: '', error_mensaje: '',
    // En WhatsApp responder dentro de la ventana de 24h es gratis.
    // En SMS no existe esa ventana: el mensaje entrante ya se cobró.
    costo_estimado_usd: esSms ? 0.0079 : 0,
    facturable: esSms ? 'si' : 'no',
    respondio: 'si',
    agendo: intencion === 'agendar' ? 'si' : 'no',
    dias_dormido: '',
    diagnostico: 'intencion=' + intencion + (cliente ? '' : ' (numero no identificado en la hoja)'),
    accion: cliente ? 'ninguna' : 'avisar_operador',
  },
}};

// Acuse de entrega, de cualquiera de los dos proveedores.
const ev = $json;

const ES = {
  sent: 'enviado', delivered: 'entregado', read: 'leido', failed: 'fallido',
  undelivered: 'no_entregado', queued: 'en_cola', accepted: 'aceptado', deleted: 'borrado',
};
const estado = ES[ev.estado_entrega] ?? ev.estado_entrega;

return { json: {
  wamid: ev.wamid,
  estado,
  facturable: ev.facturable,
  categoria: ev.categoria_real || '',
  error_mensaje: ev.motivo_error || '',
  // El envío se aceptó pero el mensaje no llegó: eso no aparece en el log del
  // workflow 01, que solo sabe si la API dijo que sí.
  accion: (estado === 'fallido' || estado === 'no_entregado') ? 'avisar_operador' : 'ninguna',
}};
